/* data/cs-c/cs-12-03.js - GENERATED by tools/build.py from data/cs/cs-12-03.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-03"] = [{"id":"cs-12-03-101","kind":"short","q":"What is C++ ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.1"],"model":[{"t":"C++ is a general purpose programming language made by Bjarne Stroustrup at Bell Laboratories.","m":1},{"t":"It is an extension of the C language and adds object oriented features such as classes and objects.","m":1},{"t":"It is fast, supports both procedural and object oriented styles, and is used for system and application software.","m":1}]},{"id":"cs-12-03-102","kind":"short","q":"What are tokens in C++ ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.2"],"model":[{"t":"Tokens are the smallest units of a C++ program that the compiler understands.","m":1},{"t":"The kinds of tokens are keywords, identifiers, constants, strings, operators and punctuation (separators).","m":1},{"t":"Example: in \"int a = 5;\" the tokens are int, a, =, 5 and ;.","m":1}]},{"id":"cs-12-03-103","kind":"short","q":"State features of C++ .","marks":4,"src":["Guide ch.3 C++, Questions 3.1, Q.3"],"model":[{"t":"It is an object oriented language: it has classes, objects, inheritance and polymorphism.","m":1},{"t":"It is a superset of C, so most C programs also run in C++.","m":1},{"t":"It supports data hiding, function overloading, operator overloading and templates.","m":1},{"t":"It is fast and portable, and it has stream input and output (cin and cout).","m":1}]},{"id":"cs-12-03-104","kind":"short","q":"Write rules for writing identifiers in C++ .","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.4"],"model":[{"t":"An identifier may contain letters (a to z, A to Z), digits (0 to 9) and the underscore, and nothing else.","m":1},{"t":"It must start with a letter or an underscore, never with a digit.","m":1},{"t":"It must not be a keyword, it is case sensitive, and it can be of any length (though only the early characters may count).","m":1}]},{"id":"cs-12-03-105","kind":"short","q":"What are data types in C++ ?","marks":4,"src":["Guide ch.3 C++, Questions 3.1, Q.5"],"model":[{"t":"A data type tells the kind of value a variable can keep and how much memory it takes.","m":1},{"t":"Built-in (basic) types: int, char, float, double, bool and void.","m":1},{"t":"Derived types: array, pointer, function, reference.","m":1},{"t":"User-defined types: structure, union, enumeration and class.","m":1}]},{"id":"cs-12-03-106","kind":"short","q":"What is constant in C++ ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.6"],"model":[{"t":"A constant is a value that does not change while the program runs.","m":1},{"t":"It can be a literal (5, 3.14, 'a') or a named constant made with the keyword const, as in: const float PI = 3.14;","m":1},{"t":"Trying to change a const variable gives a compile error.","m":1}]},{"id":"cs-12-03-107","kind":"short","q":"What is dynamic initialization of variables ? How is it achieved in C++ ?","marks":4,"src":["Guide ch.3 C++, Questions 3.1, Q.7"],"model":[{"t":"Dynamic initialization means a variable is given its starting value at run time, from an expression that is worked out when the program runs.","m":1},{"t":"In C++ a variable can be declared where it is first needed, in the middle of the code, with an expression or a function call as its value.","m":1},{"t":"Example: int sum = a + b; where a and b were read from the user earlier.","m":1},{"t":"It makes the program shorter and the variable is near its use.","m":1}]},{"id":"cs-12-03-108","kind":"short","q":"What is reference variable in C++ ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.8"],"model":[{"t":"A reference variable is another name (an alias) for an existing variable.","m":1},{"t":"It is declared with & and must be initialised when it is made: int x = 10; int &r = x;","m":1},{"t":"Changing r changes x, because both are the same memory. It is mostly used to pass arguments to functions.","m":1}]},{"id":"cs-12-03-109","kind":"short","q":"What is scope resolution operator in C++ ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.9"],"model":[{"t":"The scope resolution operator is ::","m":1},{"t":"It is used to reach a global variable that is hidden by a local variable of the same name: ::count.","m":1},{"t":"It is also used to define a member function of a class outside the class: void Student::show() { }.","m":1}]},{"id":"cs-12-03-110","kind":"short","q":"What is use of insertion and extraction operators in C++ ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.10"],"model":[{"t":"The insertion operator << sends data to an output stream, for example cout << a;","m":1},{"t":"The extraction operator >> takes data from an input stream, for example cin >> a;","m":1},{"t":"Both can be chained: cout << \"Sum = \" << s; cin >> a >> b;","m":1}]},{"id":"cs-12-03-111","kind":"short","q":"Describe operator precedence in C++ .","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.11"],"model":[{"t":"Operator precedence is the order in which operators are worked out in an expression with more than one operator.","m":1},{"t":"An operator of higher precedence is done first. For example * and / are done before + and -.","m":1},{"t":"Operators of the same precedence are done by associativity (usually left to right), and brackets can change the order.","m":1}]},{"id":"cs-12-03-112","kind":"short","q":"What are memory management operators in C++ ?","marks":4,"src":["Guide ch.3 C++, Questions 3.1, Q.12"],"model":[{"t":"C++ has two operators to manage memory while the program runs (dynamic memory): new and delete.","m":1},{"t":"new gives memory from the heap and returns its address: int *p = new int; int *a = new int[10];","m":1},{"t":"delete frees the memory that new gave: delete p; delete [] a;","m":1},{"t":"They are used instead of malloc and free of C, and they work well with classes.","m":1}]},{"id":"cs-12-03-113","kind":"short","q":"What are manipulators ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.13"],"model":[{"t":"Manipulators are special functions or objects used with << to change the way the output looks.","m":1},{"t":"Examples: endl (new line), setw(n) (sets the width of the field), setprecision(n), fixed.","m":1},{"t":"They need the header file iomanip for setw and setprecision.","m":1}]},{"id":"cs-12-03-114","kind":"prog","q":"Describe general structure of C++ program.","marks":4,"src":["Guide ch.3 C++, Questions 3.1, Q.14"],"model":[{"t":"A C++ program begins with documentation and header files (preprocessor directives such as #include <iostream>).","m":1},{"t":"Then come global declarations, class declarations and the member function definitions.","m":1},{"t":"Then comes the main() function, where the execution starts.","m":1},{"t":"main() holds the declarations and statements and ends with return 0.","m":1}],"code":"// 1. documentation (comments)\n#include <iostream>        // 2. header files\nusing namespace std;\n\nint total;                  // 3. global declarations\n\nclass Sample {              // 4. class declaration\n    int x;\npublic:\n    void set(int a) { x = a; }\n    int get() { return x; }\n};\n\nint main() {                // 5. main function\n    Sample s;\n    s.set(5);\n    cout << s.get();\n    return 0;\n}"},{"id":"cs-12-03-115","kind":"prog","q":"Write syntax of if statement in C++ .","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.15"],"model":[{"t":"The simple if statement runs a block only when the condition is true.","m":1},{"t":"The if-else statement runs one block if the condition is true and another if it is false.","m":1},{"t":"The if - else if - else ladder is used to test more than two conditions.","m":1}],"code":"if (condition) {\n    // runs when the condition is true\n}\n\nif (condition) {\n    // true part\n} else {\n    // false part\n}\n\nif (c1) {\n    // ...\n} else if (c2) {\n    // ...\n} else {\n    // ...\n}"},{"id":"cs-12-03-116","kind":"prog","q":"Write syntax for switch statement in C++ .","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.16"],"model":[{"t":"switch tests one expression against a list of constant case values.","m":1},{"t":"Each case ends with break, so the program does not run into the next case.","m":1},{"t":"The optional default part runs when no case matches.","m":1}],"code":"switch (expression) {\n    case value1:\n        // statements\n        break;\n    case value2:\n        // statements\n        break;\n    default:\n        // statements when nothing matches\n}"},{"id":"cs-12-03-117","kind":"short","q":"What are loop control statements in C++ ?","marks":4,"src":["Guide ch.3 C++, Questions 3.1, Q.17"],"model":[{"t":"A loop repeats a block of statements. The C++ loops are for, while and do-while.","m":1},{"t":"for: for (init; condition; update) { }. The count is usually known.","m":1},{"t":"while: while (condition) { }. The condition is tested first. do-while: do { } while (condition); runs at least once.","m":1},{"t":"break leaves the loop at once, and continue skips the rest of the current round.","m":1}]},{"id":"cs-12-03-118","kind":"short","q":"What is function prototyping in C++ ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.18"],"model":[{"t":"A function prototype is a declaration of a function before it is used. It tells the compiler its name, return type and the types of its arguments.","m":1},{"t":"Syntax: return_type name(type1, type2); example: int add(int, int);","m":1},{"t":"It lets the compiler check each call against the declaration; in C++ it is compulsory.","m":1}]},{"id":"cs-12-03-119","kind":"short","q":"What is advantage of inline function ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.19"],"model":[{"t":"An inline function is declared with the keyword inline. The compiler puts its code at the place of the call.","m":1},{"t":"So there is no jump to the function and no return, which saves the time of a function call.","m":1},{"t":"It suits small functions that are called many times. It makes the program larger if the function is big.","m":1}]},{"id":"cs-12-03-120","kind":"prog","q":"What is function overloading ? How can it be achieved ?","marks":4,"src":["Guide ch.3 C++, Questions 3.1, Q.20"],"model":[{"t":"Function overloading means using the same function name for different functions in the same scope.","m":1},{"t":"The functions must differ in the number or in the types of their arguments (the return type alone is not enough).","m":1},{"t":"The compiler chooses the right one from the arguments of the call.","m":1},{"t":"The example shows two add functions with different argument types.","m":1}],"code":"int add(int a, int b) { return a + b; }\nfloat add(float a, float b) { return a + b; }\nint add(int a, int b, int c) { return a + b + c; }\n\n// add(2, 3) calls the first, add(1.5f, 2.5f) the second, add(1, 2, 3) the third."},{"id":"cs-12-03-121","kind":"short","q":"What is default argument in functions ?","marks":3,"src":["Guide ch.3 C++, Questions 3.1, Q.21"],"model":[{"t":"A default argument is a value given to a parameter in the function declaration. It is used when the caller leaves that argument out.","m":1},{"t":"Example: float interest(float p, float r = 8.5); then interest(1000) uses r = 8.5.","m":1},{"t":"Default values are given from the right side of the argument list.","m":1}]},{"id":"cs-12-03-122","kind":"prog","q":"Write a program in C++ to find sum of first 100 odd numbers.","marks":5,"src":["Guide ch.3 C++, Questions 3.1, Q.22"],"model":[{"t":"Header file and main() are written correctly.","m":1},{"t":"A sum variable is set to 0 and the loop runs 100 times.","m":1},{"t":"Each odd number is added: the first is 1 and the next is 2 more.","m":1},{"t":"The total (10000) is displayed.","m":1},{"t":"The program is complete and correct.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int odd = 1, sum = 0;\n    for (int i = 1; i <= 100; i++) {\n        sum = sum + odd;\n        odd = odd + 2;\n    }\n    cout << \"Sum of first 100 odd numbers = \" << sum;   // 10000\n    return 0;\n}"},{"id":"cs-12-03-123","kind":"prog","q":"Write a program in C++ to check whether given number is prime.","marks":5,"src":["Guide ch.3 C++, Questions 3.1, Q.23"],"model":[{"t":"The number is read from the user.","m":1},{"t":"A flag shows whether a divisor is found; numbers below 2 are not prime.","m":1},{"t":"The loop tests divisors from 2 up to half of the number (or its square root).","m":1},{"t":"If any divisor divides the number exactly the flag changes and the loop stops.","m":1},{"t":"The right message is displayed.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, i, prime = 1;\n    cout << \"Enter a number: \";\n    cin >> n;\n    if (n < 2) prime = 0;\n    for (i = 2; i <= n / 2; i++) {\n        if (n % i == 0) {\n            prime = 0;\n            break;\n        }\n    }\n    if (prime) cout << n << \" is prime\";\n    else cout << n << \" is not prime\";\n    return 0;\n}"},{"id":"cs-12-03-124","kind":"prog","q":"Write program in C++ for sum of digits of given integer.","marks":5,"src":["Guide ch.3 C++, Questions 3.1, Q.24"],"model":[{"t":"The integer is read.","m":1},{"t":"A sum variable starts at 0.","m":1},{"t":"The last digit is found with n % 10 and added to the sum.","m":1},{"t":"The last digit is cut off with n / 10, and the loop repeats until n is 0.","m":1},{"t":"The sum is displayed.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, sum = 0;\n    cout << \"Enter an integer: \";\n    cin >> n;\n    while (n > 0) {\n        sum = sum + n % 10;   // last digit\n        n = n / 10;           // remove it\n    }\n    cout << \"Sum of digits = \" << sum;\n    return 0;\n}"},{"id":"cs-12-03-m125a","kind":"mcq","q":"C++ is .................","marks":1,"src":["Guide ch.3 C++, Questions 3.1, Q.25(a)"],"options":["Low level language.","Assembly language.","Object oriented programming language.","None of these."],"ans":2,"why":"C++ is a high level, object oriented programming language."},{"id":"cs-12-03-m125b","kind":"mcq","q":"................. is C++ keyword.","marks":1,"src":["Guide ch.3 C++, Questions 3.1, Q.25(b)"],"options":["Identifier","constant","const","None of these"],"ans":2,"why":"const is a keyword. \"constant\" and \"identifier\" are only ordinary words, not keywords."},{"id":"cs-12-03-m125c","kind":"mcq","q":"The range of integers in C++ is .................","marks":1,"src":["Guide ch.3 C++, Questions 3.1, Q.25(c)"],"options":["-32768 to 32767","-128 to 127","0 to 255","None of these"],"ans":0,"why":"In the board syllabus an int takes 2 bytes, so it holds -32768 to 32767. -128 to 127 is the range of a signed char."},{"id":"cs-12-03-m125d","kind":"mcq","q":"<< in C++ , is .................","marks":1,"src":["Guide ch.3 C++, Questions 3.1, Q.25(d)"],"options":["less than operator.","insertion operator.","extraction operator.","None of these."],"ans":1,"why":"<< is the insertion operator, used with cout. The extraction operator is >>, used with cin."},{"id":"cs-12-03-201","kind":"short","q":"What is array? Explain how array is declared.","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.1"],"model":[{"t":"An array is a group of elements of the same data type, kept in consecutive memory locations under one name.","m":1},{"t":"Declaration: data_type name[size]; Example: int marks[5]; makes five integers marks[0] to marks[4].","m":1},{"t":"The index starts at 0, so the last element is size - 1.","m":1},{"t":"It can be given values at the time of declaration: int a[3] = {10, 20, 30};","m":1}]},{"id":"cs-12-03-202","kind":"short","q":"Explain how array can be passed onto a function.","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.2"],"model":[{"t":"The name of the array is passed as the argument. It stands for the address of the first element, so the function works on the original array (not a copy).","m":1},{"t":"The size is usually passed as a second argument.","m":1},{"t":"In the function header the parameter is written as an array: void show(int a[], int n).","m":1},{"t":"Call: show(marks, 5);","m":1}]},{"id":"cs-12-03-203","kind":"short","q":"What are pointers ?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.3"],"model":[{"t":"A pointer is a variable that stores the memory address of another variable.","m":1},{"t":"It is declared with *, for example int *p; and given an address with &, for example p = &x;","m":1},{"t":"The value at the address is reached with *p.","m":1}]},{"id":"cs-12-03-204","kind":"short","q":"What are advantages of pointers ?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.4"],"model":[{"t":"They allow dynamic memory allocation: memory can be taken and released while the program runs.","m":1},{"t":"They make arrays, strings and the passing of arguments to functions faster.","m":1},{"t":"They are used to build linked lists, stacks and trees, and a function can change the original values.","m":1}]},{"id":"cs-12-03-205","kind":"short","q":"What operations are permitted in pointer arithmetic?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.5"],"model":[{"t":"A number can be added to a pointer or subtracted from it (p + 2, p - 1): the pointer moves by that many elements.","m":1},{"t":"The ++ and -- operators can be used on a pointer, to move to the next or the previous element.","m":1},{"t":"One pointer can be subtracted from another of the same type (p2 - p1), which gives the number of elements between them. Two pointers cannot be added.","m":1}]},{"id":"cs-12-03-206","kind":"short","q":"What is 'call by value' and 'call by reference'?","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.6"],"model":[{"t":"Call by value: a copy of the argument is given to the function. Changes made in the function do not change the original variable.","m":1},{"t":"Call by reference: the address (a pointer) or a reference of the variable is given. The function works on the original, so the changes remain.","m":1},{"t":"Example of reference: void swap(int &a, int &b). Example of pointer: void swap(int *a, int *b).","m":1},{"t":"Call by reference is used to change the original values or to avoid copying big data.","m":1}]},{"id":"cs-12-03-207","kind":"short","q":"Describe close correspondence between array and pointer.","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.7"],"model":[{"t":"The name of an array is a constant pointer to its first element: a is the same as &a[0].","m":1},{"t":"So a + i points to a[i], and *(a + i) is the same as a[i].","m":1},{"t":"A pointer can be set to an array (p = a) and then used like the array: p[i] or *(p + i).","m":1},{"t":"The difference is that an array name cannot be changed, but a pointer can be moved to a new place.","m":1}]},{"id":"cs-12-03-208","kind":"short","q":"What are strings ?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.8"],"model":[{"t":"A string is a group of characters used to store text, such as a name.","m":1},{"t":"In C++ it is a character array that ends with the null character '\\0'. Example: char name[20] = \"Prakash\"; (7 characters, 8 places with the null).","m":1},{"t":"Strings are read with cin, gets or getline and are handled by functions like strlen, strcpy and strcat.","m":1}]},{"id":"cs-12-03-209","kind":"short","q":"What is object oriented programming ?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.9"],"model":[{"t":"Object oriented programming (OOP) is a way of writing programs around objects instead of around functions.","m":1},{"t":"An object keeps data and the functions that work on the data together, in one unit.","m":1},{"t":"It is built on classes, data hiding, inheritance and polymorphism. C++ and Java are OOP languages.","m":1}]},{"id":"cs-12-03-210","kind":"short","q":"State features of object oriented programming.","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.10"],"model":[{"t":"Class and object: a class is the plan and an object is one real item made from it.","m":1},{"t":"Data abstraction and encapsulation: data and functions are bound together, and the details are hidden.","m":1},{"t":"Inheritance: a new class gets the properties of an old class. Polymorphism: one name, many forms.","m":1},{"t":"Data hiding keeps the data safe from outside use. Programs are made bottom-up and are easy to extend and reuse.","m":1}]},{"id":"cs-12-03-211","kind":"short","q":"What are objects in C++ ?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.11"],"model":[{"t":"An object is a real item made from a class. It has its own data (attributes) and uses the functions of the class (behaviour).","m":1},{"t":"It takes memory when it is created. Example: Student s1, s2; makes two objects of the class Student.","m":1},{"t":"The members are used with the dot operator: s1.show();","m":1}]},{"id":"cs-12-03-212","kind":"short","q":"What is class in C++?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.12"],"model":[{"t":"A class is a user-defined type that groups data members and member functions together.","m":1},{"t":"It is a plan (template) from which objects are made; it takes no memory till an object is made.","m":1},{"t":"Syntax: class Name { private: ...; public: ...; };  The members are private unless made public.","m":1}]},{"id":"cs-12-03-213","kind":"short","q":"What is inheritance ?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.13"],"model":[{"t":"Inheritance is the process by which a new class (the derived class) takes the data and functions of an existing class (the base class).","m":1},{"t":"The derived class can add its own members, so the old code is reused.","m":1},{"t":"Syntax: class Derived : public Base { ... };","m":1}]},{"id":"cs-12-03-214","kind":"short","q":"What is polymorphism?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.14"],"model":[{"t":"Polymorphism means \"many forms\": one name or operator behaves in different ways in different places.","m":1},{"t":"At compile time it is shown by function overloading and operator overloading.","m":1},{"t":"At run time it is shown by virtual functions.","m":1}]},{"id":"cs-12-03-215","kind":"short","q":"What is data abstraction?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.15"],"model":[{"t":"Data abstraction means showing only the necessary features of an object and hiding the details of how it works.","m":1},{"t":"The user uses the public functions of the class and need not know how they are written inside.","m":1},{"t":"A class is a data type made by abstraction (an abstract data type).","m":1}]},{"id":"cs-12-03-216","kind":"short","q":"What is data hiding?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.16"],"model":[{"t":"Data hiding means the data of a class is kept private, so that functions outside the class cannot reach it directly.","m":1},{"t":"The data can be used only through the public member functions of the class.","m":1},{"t":"It keeps the data safe from accidental change.","m":1}]},{"id":"cs-12-03-217","kind":"short","q":"What is data encapsulation?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.17"],"model":[{"t":"Encapsulation is putting the data and the functions that work on it together into one unit, a class.","m":1},{"t":"The class is like a capsule: its inside is hidden and its public part is the way to use it.","m":1},{"t":"It supports data hiding and makes the code easy to manage.","m":1}]},{"id":"cs-12-03-218","kind":"short","q":"How member functions are defined?","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.18"],"model":[{"t":"A member function can be defined inside the class, like a normal function. It is then treated as inline.","m":1},{"t":"It can be defined outside the class. Inside the class only the prototype is written.","m":1},{"t":"Outside, the scope resolution operator is used in the header: return_type ClassName::name(arguments) { }.","m":1},{"t":"Example: void Student::show() { cout << roll; }","m":1}]},{"id":"cs-12-03-219","kind":"short","q":"Explain how to form an array of objects.","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.19"],"model":[{"t":"An array of objects is an array whose elements are objects of one class.","m":1},{"t":"Declaration: ClassName arrayname[size]; example: Student s[10];","m":1},{"t":"Each element is used with the dot operator: s[i].getdata(); s[i].show();","m":1},{"t":"A loop is used to read or show all the objects.","m":1}]},{"id":"cs-12-03-220","kind":"short","q":"What is friend function? What are advantages of it?","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.20"],"model":[{"t":"A friend function is a function that is not a member of a class but is allowed to use its private and protected members.","m":1},{"t":"It is declared inside the class with the keyword friend. It is defined outside like a normal function, and is called without an object and the dot operator.","m":1},{"t":"Advantage: one function can work with the private data of two or more classes (for example to add two objects).","m":1},{"t":"Advantage: it is useful in operator overloading, where the operator is not a member.","m":1}]},{"id":"cs-12-03-221","kind":"short","q":"What is constructor?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.21"],"model":[{"t":"A constructor is a special member function that runs automatically when an object is created.","m":1},{"t":"It has the same name as the class and has no return type.","m":1},{"t":"It is used to give starting values to the data members of the object.","m":1}]},{"id":"cs-12-03-222","kind":"short","q":"What is destructor?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.22"],"model":[{"t":"A destructor is a special member function that runs automatically when an object is destroyed (goes out of scope).","m":1},{"t":"It has the name of the class with a ~ in front: ~Student();  It has no arguments and no return type.","m":1},{"t":"It is used to free the memory or other resources taken by the object.","m":1}]},{"id":"cs-12-03-223","kind":"short","q":"What are syntax rules for writing constructor function?","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.23"],"model":[{"t":"The constructor name must be the same as the class name.","m":1},{"t":"It has no return type, not even void, and it cannot return a value.","m":1},{"t":"It is usually public, it may have arguments, and it can be overloaded.","m":1},{"t":"It is called automatically when an object is made, and it cannot be called like a normal function or inherited.","m":1}]},{"id":"cs-12-03-224","kind":"short","q":"What is default constructor?","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.24"],"model":[{"t":"A default constructor is a constructor that takes no arguments.","m":1},{"t":"It is called when an object is made without any value, such as Student s;","m":1},{"t":"If the programmer writes no constructor, the compiler makes an empty one.","m":1}]},{"id":"cs-12-03-225","kind":"short","q":"How dynamic initialization of object is achieved?","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.25"],"model":[{"t":"Dynamic initialization means an object is given its starting values at run time.","m":1},{"t":"The values are read from the user or worked out in the program, and are passed to a parameterised constructor.","m":1},{"t":"Example: int a, b; cin >> a >> b; Rectangle r(a, b);","m":1},{"t":"The right constructor is chosen from the arguments (constructor overloading).","m":1}]},{"id":"cs-12-03-226","kind":"short","q":"What is copy constructor? When is it used?","marks":4,"src":["Guide ch.3 C++, Questions 3.2, Q.26"],"model":[{"t":"A copy constructor makes a new object as a copy of an existing object of the same class.","m":1},{"t":"Syntax: ClassName(ClassName &obj); The object is passed by reference.","m":1},{"t":"It is used when an object is made from another object (Student s2(s1); or s2 = s1 at declaration), when an object is passed by value, and when it is returned by value.","m":1},{"t":"It is needed when the class has a pointer, to copy the data and not only the address.","m":1}]},{"id":"cs-12-03-227","kind":"short","q":"Write syntax rules for writing destructor function.","marks":3,"src":["Guide ch.3 C++, Questions 3.2, Q.27"],"model":[{"t":"The name is the class name with a tilde ~ before it.","m":1},{"t":"It has no arguments, no return type, and cannot be overloaded; a class has only one destructor.","m":1},{"t":"It is called automatically when the object ends, and cannot be inherited.","m":1}]},{"id":"cs-12-03-228","kind":"prog","q":"Write a program in C++ for addition of two matrices.","marks":5,"src":["Guide ch.3 C++, Questions 3.2, Q.28"],"model":[{"t":"Header, declarations and the two matrices of the same size are written.","m":1},{"t":"The elements of both matrices are read with nested loops.","m":1},{"t":"Each element of the answer is the sum of the elements at the same place.","m":1},{"t":"The answer matrix is displayed row by row.","m":1},{"t":"The program is complete and correct.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[3][3], b[3][3], c[3][3], i, j;\n    cout << \"Enter matrix A (3 x 3):\\n\";\n    for (i = 0; i < 3; i++)\n        for (j = 0; j < 3; j++)\n            cin >> a[i][j];\n    cout << \"Enter matrix B (3 x 3):\\n\";\n    for (i = 0; i < 3; i++)\n        for (j = 0; j < 3; j++)\n            cin >> b[i][j];\n    for (i = 0; i < 3; i++)\n        for (j = 0; j < 3; j++)\n            c[i][j] = a[i][j] + b[i][j];\n    cout << \"Sum:\\n\";\n    for (i = 0; i < 3; i++) {\n        for (j = 0; j < 3; j++)\n            cout << c[i][j] << \" \";\n        cout << \"\\n\";\n    }\n    return 0;\n}"},{"id":"cs-12-03-229","kind":"prog","q":"Write a program in C++ for addition of diagonal elements of matrix.","marks":5,"src":["Guide ch.3 C++, Questions 3.2, Q.29"],"model":[{"t":"A square matrix is declared and read.","m":1},{"t":"A sum variable starts at 0.","m":1},{"t":"The diagonal elements are those with equal row and column index: a[i][i].","m":1},{"t":"One loop adds them.","m":1},{"t":"The sum is displayed.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[3][3], i, j, sum = 0;\n    cout << \"Enter a 3 x 3 matrix:\\n\";\n    for (i = 0; i < 3; i++)\n        for (j = 0; j < 3; j++)\n            cin >> a[i][j];\n    for (i = 0; i < 3; i++)\n        sum = sum + a[i][i];\n    cout << \"Sum of diagonal elements = \" << sum;\n    return 0;\n}"},{"id":"cs-12-03-230","kind":"prog","q":"Write a program in C++ to find transpose of a given matrix.","marks":5,"src":["Guide ch.3 C++, Questions 3.2, Q.30"],"model":[{"t":"The matrix is declared and its elements are read.","m":1},{"t":"The transpose is a matrix in which the rows and columns are exchanged.","m":1},{"t":"Element t[j][i] gets the value of a[i][j] in nested loops.","m":1},{"t":"The transpose is displayed row by row.","m":1},{"t":"The program is complete and correct.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[3][3], t[3][3], i, j;\n    cout << \"Enter a 3 x 3 matrix:\\n\";\n    for (i = 0; i < 3; i++)\n        for (j = 0; j < 3; j++)\n            cin >> a[i][j];\n    for (i = 0; i < 3; i++)\n        for (j = 0; j < 3; j++)\n            t[j][i] = a[i][j];\n    cout << \"Transpose:\\n\";\n    for (i = 0; i < 3; i++) {\n        for (j = 0; j < 3; j++)\n            cout << t[i][j] << \" \";\n        cout << \"\\n\";\n    }\n    return 0;\n}"},{"id":"cs-12-03-231","kind":"prog","q":"Write a program in C++ for concatenation of two strings.","marks":5,"src":["Guide ch.3 C++, Questions 3.2, Q.31"],"model":[{"t":"Two character arrays are declared and read, with space for both together.","m":1},{"t":"The end of the first string is found (the null character).","m":1},{"t":"The characters of the second string are copied one by one after it.","m":1},{"t":"A null character is put at the end of the new string.","m":1},{"t":"The joined string is displayed.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    char s1[50], s2[25];\n    int i = 0, j = 0;\n    cout << \"Enter first string: \";\n    cin >> s1;\n    cout << \"Enter second string: \";\n    cin >> s2;\n    while (s1[i] != '\\0')\n        i++;                       // go to the end of s1\n    while (s2[j] != '\\0') {\n        s1[i] = s2[j];             // copy s2 after it\n        i++;\n        j++;\n    }\n    s1[i] = '\\0';\n    cout << \"Joined string: \" << s1;\n    return 0;\n}"},{"id":"cs-12-03-232","kind":"prog","q":"Write a program in C++ to find a substring in the given string.","marks":5,"src":["Guide ch.3 C++, Questions 3.2, Q.32"],"model":[{"t":"The main string and the substring are read.","m":1},{"t":"The lengths of both strings are found.","m":1},{"t":"The substring is compared with the main string at each starting place.","m":1},{"t":"If all its characters match at a place, the place is shown and the search ends.","m":1},{"t":"A message is shown if the substring is not found.","m":1}],"code":"#include <iostream>\n#include <string.h>\nusing namespace std;\n\nint main() {\n    char str[100], sub[30];\n    int i, j, found = 0;\n    cout << \"Enter the string: \";\n    cin >> str;\n    cout << \"Enter the substring: \";\n    cin >> sub;\n    int n = strlen(str), m = strlen(sub);\n    for (i = 0; i + m <= n; i++) {\n        for (j = 0; j < m; j++)\n            if (str[i + j] != sub[j])\n                break;\n        if (j == m) {\n            cout << \"Found at position \" << i + 1;\n            found = 1;\n            break;\n        }\n    }\n    if (!found) cout << \"Substring not found\";\n    return 0;\n}"},{"id":"cs-12-03-233","kind":"prog","q":"Write an object oriented program in C++ to perform trigonometric operations on complex numbers.","marks":5,"src":["Guide ch.3 C++, Questions 3.2, Q.33"],"model":[{"t":"A class Complex with real and imaginary parts is written, with functions to read and to show the number.","m":1},{"t":"The operations are member functions (for example add, multiply and the modulus), each working on objects.","m":1},{"t":"Trigonometric operations on a complex number z = x + iy use the formulas for sin z, cos z and so on, worked out from x and y.","m":1},{"t":"The functions are called from main() for objects of the class.","m":1},{"t":"The program is complete and the answers are displayed.","m":1}],"code":"#include <iostream>\n#include <math.h>\nusing namespace std;\n\nclass Complex {\n    float x, y;                         // z = x + i y\npublic:\n    void get() { cout << \"Enter real and imaginary parts: \"; cin >> x >> y; }\n    void show(const char *label) { cout << label << x << (y >= 0 ? \" + \" : \" - \") << fabs(y) << \"i\\n\"; }\n    Complex sine() {                    // sin(x + iy) = sin x cosh y + i cos x sinh y\n        Complex r;\n        r.x = sin(x) * cosh(y);\n        r.y = cos(x) * sinh(y);\n        return r;\n    }\n    Complex cosine() {                  // cos(x + iy) = cos x cosh y - i sin x sinh y\n        Complex r;\n        r.x = cos(x) * cosh(y);\n        r.y = -sin(x) * sinh(y);\n        return r;\n    }\n};\n\nint main() {\n    Complex z, s, c;\n    z.get();\n    s = z.sine();\n    c = z.cosine();\n    s.show(\"sin z = \");\n    c.show(\"cos z = \");\n    return 0;\n}"},{"id":"cs-12-03-234","kind":"prog","q":"Write a program using constructor and destructor, to find factorial of a number.","marks":5,"src":["Guide ch.3 C++, Questions 3.2, Q.34"],"model":[{"t":"A class with a data member for the number and the factorial is written.","m":1},{"t":"The constructor gives the number its value and works out the factorial with a loop.","m":1},{"t":"A member function displays the result.","m":1},{"t":"The destructor is written and shows a message when the object ends.","m":1},{"t":"main() makes an object and the program is complete.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nclass Factorial {\n    int n;\n    long fact;\npublic:\n    Factorial(int num) {                // constructor\n        n = num;\n        fact = 1;\n        for (int i = 1; i <= n; i++)\n            fact = fact * i;\n    }\n    void show() { cout << \"Factorial of \" << n << \" = \" << fact << \"\\n\"; }\n    ~Factorial() { cout << \"Object destroyed\\n\"; }   // destructor\n};\n\nint main() {\n    int num;\n    cout << \"Enter a number: \";\n    cin >> num;\n    Factorial f(num);\n    f.show();\n    return 0;\n}"},{"id":"cs-12-03-m235a","kind":"mcq","q":"A pointer is a variable that holds ................. of another variable.","marks":1,"src":["Guide ch.3 C++, Questions 3.2, Q.35(a)"],"options":["Value","Memory address","Data type","None of these"],"ans":1,"why":"A pointer stores the memory address of another variable, not its value."},{"id":"cs-12-03-m235b","kind":"mcq","q":"\"Prakash\" is a string of length .................","marks":1,"src":["Guide ch.3 C++, Questions 3.2, Q.35(b)"],"options":["7","8","6","1"],"ans":0,"why":"P-r-a-k-a-s-h has 7 characters. The null character at the end is not counted in the length (it takes one extra place in memory)."},{"id":"cs-12-03-m235c","kind":"mcq","q":"Object is a variable of type .................","marks":1,"src":["Guide ch.3 C++, Questions 3.2, Q.35(c)"],"options":["Integer","Character","Real","Class"],"ans":3,"why":"An object is a variable whose type is a class."},{"id":"cs-12-03-301","kind":"short","q":"What is operator overloading?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.1"],"model":[{"t":"Operator overloading means giving an existing operator (such as + or -) an extra meaning for the objects of a class.","m":1},{"t":"Example: with overloading, c3 = c1 + c2; can add two Complex objects.","m":1},{"t":"The meaning for the built-in types does not change. It is a way of showing polymorphism at compile time.","m":1}]},{"id":"cs-12-03-302","kind":"short","q":"List the operators which cannot be overloaded.","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.2"],"model":[{"t":"The scope resolution operator ::","m":1},{"t":"The member access operators . and .* (dot and pointer to member).","m":1},{"t":"The conditional operator ?: and the sizeof operator.","m":1}]},{"id":"cs-12-03-303","kind":"short","q":"How to define operator overloading?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.3"],"model":[{"t":"It is defined with a special member function, called an operator function, with the keyword operator.","m":1},{"t":"Syntax: return_type ClassName::operator op (arguments) { body }  where op is the operator to be overloaded.","m":1},{"t":"For a unary operator a member function takes no argument; for a binary operator it takes one argument (the right operand).","m":1},{"t":"Example: Complex operator + (Complex c) { Complex t; t.x = x + c.x; t.y = y + c.y; return t; }","m":1}]},{"id":"cs-12-03-304","kind":"short","q":"Describe the process of overloading.","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.4"],"model":[{"t":"First a class is made for the data type on which the operator will work.","m":1},{"t":"Then the operator function is declared inside the class (a member or a friend function) and defined with the keyword operator.","m":1},{"t":"In main(), the operator is used on the objects in the usual way, for example c3 = c1 + c2;","m":1},{"t":"The compiler turns this into a call of the operator function: c3 = c1.operator+(c2);","m":1}]},{"id":"cs-12-03-305","kind":"short","q":"What are rules for operator overloading?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.5"],"model":[{"t":"Only existing operators can be overloaded; new operators cannot be made.","m":1},{"t":"The operators :: . .* ?: and sizeof cannot be overloaded.","m":1},{"t":"The number of operands cannot be changed, and the precedence of the operator stays the same.","m":1},{"t":"At least one operand must be an object of a user-defined class; overloaded operators cannot change the meaning for the basic data types.","m":1}]},{"id":"cs-12-03-306","kind":"short","q":"What is type conversion?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.6"],"model":[{"t":"Type conversion means changing a value of one data type into another data type.","m":1},{"t":"Implicit conversion is done by the compiler by itself (for example int to float in a mixed expression).","m":1},{"t":"Explicit conversion is asked by the programmer with a cast, for example (float)a / b.","m":1}]},{"id":"cs-12-03-307","kind":"short","q":"How conversion from built in type to class type is achieved?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.7"],"model":[{"t":"It is done with a constructor that takes one argument of the built-in type.","m":1},{"t":"The constructor turns the value into an object of the class.","m":1},{"t":"Example: class Time { int h, m; public: Time(int minutes) { h = minutes / 60; m = minutes % 60; } };","m":1},{"t":"Then Time t = 135; makes the object from the integer.","m":1}]},{"id":"cs-12-03-308","kind":"short","q":"Explain class to basic type conversion.","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.8"],"model":[{"t":"To change an object of a class to a built-in type, a conversion function is written in the class, with the keyword operator.","m":1},{"t":"Syntax: operator typename() { ... return value; } It has no return type written and no arguments.","m":1},{"t":"Example: operator int() { return h * 60 + m; } in class Time.","m":1},{"t":"Then int x = t; changes the object t into an integer.","m":1}]},{"id":"cs-12-03-309","kind":"short","q":"Explain conversion from one class to another class.","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.9"],"model":[{"t":"An object of one class (the source) can be changed into an object of another class (the destination).","m":1},{"t":"It is done with a conversion function in the source class, or with a constructor in the destination class that takes the source object.","m":1},{"t":"In the destination constructor the data of the source object is used to set the data of the new object.","m":1},{"t":"Example: class B has a constructor B(A a) { value = a.get(); } so B b = a; works.","m":1}]},{"id":"cs-12-03-310","kind":"short","q":"What is inheritance?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.10"],"model":[{"t":"Inheritance is the process of making a new class (derived class) from an existing class (base class).","m":1},{"t":"The derived class gets the data and functions of the base class and can add its own.","m":1},{"t":"Syntax: class Derived : public Base { };  It gives reuse of code.","m":1}]},{"id":"cs-12-03-311","kind":"short","q":"What are different types of inheritance?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.11"],"model":[{"t":"Single inheritance: one derived class from one base class.","m":1},{"t":"Multilevel inheritance: a class is derived from a derived class (a chain, A to B to C).","m":1},{"t":"Multiple inheritance: one derived class from two or more base classes.","m":1},{"t":"Hierarchical inheritance: many derived classes from one base class. (A mix of these is called hybrid inheritance.)","m":1}]},{"id":"cs-12-03-312","kind":"short","q":"What is advantage of inheritance?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.12"],"model":[{"t":"Reusability: the code of an existing class is used again, so less code is written.","m":1},{"t":"It saves time and reduces mistakes, because the base class is already tested.","m":1},{"t":"It gives a natural hierarchy, and a class can be extended without changing the old one.","m":1}]},{"id":"cs-12-03-313","kind":"short","q":"What is single inheritance?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.13"],"model":[{"t":"In single inheritance a derived class has only one base class.","m":1},{"t":"Example: class Student is derived from class Person.","m":1},{"t":"Syntax: class B : public A { };","m":1}]},{"id":"cs-12-03-314","kind":"short","q":"What is multilevel inheritance?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.14"],"model":[{"t":"In multilevel inheritance a class is derived from a class that is itself derived from another class.","m":1},{"t":"It forms a chain: A is the base of B, and B is the base of C. C gets the members of both B and A.","m":1},{"t":"Syntax: class B : public A { };  class C : public B { };","m":1}]},{"id":"cs-12-03-315","kind":"short","q":"What is multiple inheritance?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.15"],"model":[{"t":"In multiple inheritance a derived class has two or more base classes.","m":1},{"t":"The derived class gets the members of all of its base classes.","m":1},{"t":"Syntax: class C : public A, public B { };","m":1}]},{"id":"cs-12-03-316","kind":"short","q":"What is hierarchical inheritance?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.16"],"model":[{"t":"In hierarchical inheritance two or more derived classes are made from one base class.","m":1},{"t":"The common members are in the base class and each derived class adds its own.","m":1},{"t":"Syntax: class B : public A { };  class C : public A { };","m":1}]},{"id":"cs-12-03-317","kind":"short","q":"What are virtual base classes?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.17"],"model":[{"t":"A virtual base class is a base class that is declared with the keyword virtual when it is inherited.","m":1},{"t":"It is needed when a class gets the same base class by more than one path (for example in hybrid inheritance), which would give two copies of its members and cause confusion.","m":1},{"t":"The keyword virtual makes the derived classes share one copy of the base class members.","m":1},{"t":"Syntax: class B : virtual public A { };  class C : virtual public A { };  class D : public B, public C { };","m":1}]},{"id":"cs-12-03-318","kind":"short","q":"What is polymorphism?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.18"],"model":[{"t":"Polymorphism means one name with many forms: the same function name or operator does different jobs.","m":1},{"t":"Compile time polymorphism: function overloading and operator overloading (early binding).","m":1},{"t":"Run time polymorphism: virtual functions (late binding).","m":1}]},{"id":"cs-12-03-319","kind":"short","q":"What are virtual functions?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.19"],"model":[{"t":"A virtual function is a member function of the base class that is declared with the keyword virtual, and is redefined in the derived class.","m":1},{"t":"When it is called through a base class pointer, the function of the object that the pointer points to is run (not the function of the pointer type).","m":1},{"t":"This choice is made at run time. It gives run time polymorphism.","m":1},{"t":"Example: virtual void show();","m":1}]},{"id":"cs-12-03-320","kind":"short","q":"What is early binding?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.20"],"model":[{"t":"Binding means joining a function call with the code of the function.","m":1},{"t":"In early binding (static binding) this is done at compile time.","m":1},{"t":"Normal functions and overloaded functions use early binding. It is faster.","m":1}]},{"id":"cs-12-03-321","kind":"short","q":"What is late binding?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.21"],"model":[{"t":"In late binding (dynamic binding) the function call is joined to the function code at run time.","m":1},{"t":"It is used with virtual functions called through a base class pointer.","m":1},{"t":"It is a little slower but gives flexibility: the right function is chosen from the real object.","m":1}]},{"id":"cs-12-03-322","kind":"short","q":"Write rules for virtual functions.","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.22"],"model":[{"t":"A virtual function must be a member of a class. It cannot be a static member or a friend function.","m":1},{"t":"It is accessed through a base class pointer to get run time polymorphism.","m":1},{"t":"The prototype in the base class and in the derived class must be the same.","m":1},{"t":"A virtual function need not be redefined in the derived class; then the base class version is used. A class cannot have a virtual constructor but can have a virtual destructor.","m":1}]},{"id":"cs-12-03-323","kind":"short","q":"What is pure virtual function?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.23"],"model":[{"t":"A pure virtual function is a virtual function with no body in the base class.","m":1},{"t":"It is written as: virtual void show() = 0;","m":1},{"t":"A class with a pure virtual function is an abstract class: no object can be made from it, and the derived classes must define the function.","m":1}]},{"id":"cs-12-03-324","kind":"short","q":"What is file?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.24"],"model":[{"t":"A file is a collection of related data kept on a storage device such as a disk, with a name.","m":1},{"t":"It keeps data permanently, even after the program ends.","m":1},{"t":"In C++ a file is used through a stream, and the data can be text or binary.","m":1}]},{"id":"cs-12-03-325","kind":"short","q":"What is input stream and output stream?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.25"],"model":[{"t":"A stream is a flow of data between the program and a device or a file.","m":1},{"t":"Input stream: it carries data into the program, from the keyboard or from a file.","m":1},{"t":"Output stream: it carries data out of the program, to the screen or to a file.","m":1}]},{"id":"cs-12-03-326","kind":"short","q":"What are classes for file stream operations?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.26"],"model":[{"t":"ifstream: used to read from a file (an input file stream).","m":1},{"t":"ofstream: used to write to a file (an output file stream).","m":1},{"t":"fstream: used for both reading and writing. These classes are in the header file fstream.","m":1}]},{"id":"cs-12-03-327","kind":"short","q":"How to open a file?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.27"],"model":[{"t":"First the header file fstream is included, and an object of ifstream, ofstream or fstream is made.","m":1},{"t":"The file is opened with the open() function: ofstream out; out.open(\"data.txt\");","m":1},{"t":"It can also be opened with the constructor: ofstream out(\"data.txt\");","m":1},{"t":"After the work, the file is closed with close(): out.close();","m":1}]},{"id":"cs-12-03-328","kind":"short","q":"What are different file modes?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.28"],"model":[{"t":"ios::in opens a file for reading, and ios::out opens it for writing (the old contents are lost).","m":1},{"t":"ios::app opens for writing at the end (append) and ios::ate puts the pointer at the end on opening.","m":1},{"t":"ios::binary opens the file as a binary file.","m":1},{"t":"ios::trunc deletes the contents if the file exists, and ios::nocreate/ios::noreplace control creating or replacing. Modes can be joined with | .","m":1}]},{"id":"cs-12-03-329","kind":"short","q":"What is file pointer?","marks":3,"src":["Guide ch.3 C++, Questions 3.3, Q.29"],"model":[{"t":"A file pointer shows the position in a file where the next read or write will happen.","m":1},{"t":"Each file has a get pointer (for reading) and a put pointer (for writing).","m":1},{"t":"The functions seekg(), seekp(), tellg() and tellp() move and find them.","m":1}]},{"id":"cs-12-03-330","kind":"short","q":"How to perform sequential input / output operations on file?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.30"],"model":[{"t":"Sequential access reads or writes the data from the beginning to the end, in order.","m":1},{"t":"The functions put() and get() handle one character; the operators << and >> and the functions getline() handle words and lines.","m":1},{"t":"Open the file, loop until the end of file (eof()), and close it.","m":1},{"t":"Example: while (in.get(ch)) cout << ch;","m":1}]},{"id":"cs-12-03-331","kind":"short","q":"How binary file operations are performed?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.31"],"model":[{"t":"A binary file keeps data in the same form as in memory, not as text. It is opened with ios::binary.","m":1},{"t":"write() writes a block of bytes: file.write((char *) &obj, sizeof(obj));","m":1},{"t":"read() reads a block of bytes: file.read((char *) &obj, sizeof(obj));","m":1},{"t":"The file is closed with close() after the work.","m":1}]},{"id":"cs-12-03-332","kind":"short","q":"How to write class object in file.","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.32"],"model":[{"t":"The file is opened as an ofstream in binary mode: ofstream f(\"stud.dat\", ios::binary);","m":1},{"t":"The object is written as one block with write(): f.write((char *) &s, sizeof(s));","m":1},{"t":"Here s is the object and sizeof(s) is its size in bytes.","m":1},{"t":"The file is closed with f.close(). It can be read back with read().","m":1}]},{"id":"cs-12-03-333","kind":"short","q":"Describe random access of file?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.33"],"model":[{"t":"Random access means the file pointer can be moved to any place of the file and the data read or written there, without going through the earlier data.","m":1},{"t":"seekg(n) moves the get pointer (reading) to byte n, and seekp(n) moves the put pointer (writing).","m":1},{"t":"Forms: seekg(offset, ios::beg or ios::cur or ios::end). tellg() and tellp() tell the present position.","m":1},{"t":"Example: to read the 3rd record: f.seekg(2 * sizeof(rec)); f.read((char *) &rec, sizeof(rec));","m":1}]},{"id":"cs-12-03-334","kind":"short","q":"What are command line arguments?","marks":4,"src":["Guide ch.3 C++, Questions 3.3, Q.34"],"model":[{"t":"Command line arguments are values given to a program on the command line when it is started.","m":1},{"t":"main() receives them as: int main(int argc, char *argv[]).","m":1},{"t":"argc is the number of arguments (the program name counts as one), and argv is an array of strings that holds them.","m":1},{"t":"Example: for \"copy a.txt b.txt\", argc is 3, argv[1] is \"a.txt\" and argv[2] is \"b.txt\".","m":1}]},{"id":"cs-12-03-335","kind":"prog","q":"Write a program for overloading of unary + operator.","marks":5,"src":["Guide ch.3 C++, Questions 3.3, Q.35"],"model":[{"t":"A class with data members is written (for example x and y).","m":1},{"t":"The operator function for unary + is written with the keyword operator and no argument.","m":1},{"t":"Its work is defined (here: it changes any negative value to positive).","m":1},{"t":"main() makes an object and uses +obj.","m":1},{"t":"The program is complete and the result is displayed.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nclass Number {\n    int x, y;\npublic:\n    Number(int a = 0, int b = 0) { x = a; y = b; }\n    void operator +() {            // unary +: make the values positive\n        if (x < 0) x = -x;\n        if (y < 0) y = -y;\n    }\n    void show() { cout << \"x = \" << x << \", y = \" << y << \"\\n\"; }\n};\n\nint main() {\n    Number n(-5, -8);\n    cout << \"Before: \";\n    n.show();\n    +n;                              // calls operator +()\n    cout << \"After:  \";\n    n.show();\n    return 0;\n}"},{"id":"cs-12-03-336","kind":"prog","q":"Write a program for basic to class data conversion.","marks":5,"src":["Guide ch.3 C++, Questions 3.3, Q.36"],"model":[{"t":"A class is written with data members (for example hours and minutes).","m":1},{"t":"A constructor with one argument of a built-in type (int) is written. It does the conversion.","m":1},{"t":"It uses the integer to set the data members of the object.","m":1},{"t":"A function to display the object is written, and main() makes the object from a basic value.","m":1},{"t":"The program is complete and the result is displayed.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nclass Time {\n    int hours, minutes;\npublic:\n    Time(int total) {              // basic (int) to class conversion\n        hours = total / 60;\n        minutes = total % 60;\n    }\n    void show() { cout << hours << \" hours \" << minutes << \" minutes\\n\"; }\n};\n\nint main() {\n    int mins = 135;\n    Time t = mins;                   // int is converted into a Time object\n    t.show();                        // 2 hours 15 minutes\n    return 0;\n}"},{"id":"cs-12-03-m337a","kind":"mcq","q":"................. operator cannot be overloaded.","marks":1,"src":["Guide ch.3 C++, Questions 3.3, Q.37(a)"],"options":["unary","binary +","scope resolution","none of these"],"ans":2,"why":"The scope resolution operator :: cannot be overloaded. Unary and binary operators like + can be."},{"id":"cs-12-03-m337b","kind":"mcq","q":"A derived class with several base classes is ................. inheritance.","marks":1,"src":["Guide ch.3 C++, Questions 3.3, Q.37(b)"],"options":["single","multiple","multilevel","hierarchical"],"ans":1,"why":"More than one base class means multiple inheritance."},{"id":"cs-12-03-m337c","kind":"mcq","q":"Binding of an object to its function call at compile time is ................. binding.","marks":1,"src":["Guide ch.3 C++, Questions 3.3, Q.37(c)"],"options":["early","late","middle","none of these"],"ans":0,"why":"Binding done at compile time is early (static) binding. Binding at run time is late binding."},{"id":"cs-12-03-m337d","kind":"mcq","q":"Late binding is also called as ...............","marks":1,"src":["Guide ch.3 C++, Questions 3.3, Q.37(d)"],"options":["dynamic binding","static binding","early binding","none of these"],"ans":0,"why":"Late binding happens at run time, so it is dynamic binding."},{"id":"cs-12-03-m337e","kind":"mcq","q":"............... class is used to write a stream of objects in a file.","marks":1,"src":["Guide ch.3 C++, Questions 3.3, Q.37(e)"],"options":["ofstream","ifstream","stream","none of these"],"ans":0,"why":"ofstream writes to a file. ifstream reads from a file."},{"id":"cs-12-03-p901","kind":"mcq","q":"When a member function is defined inside the class, then it is treated as .........","marks":1,"src":["HSC March 2023 Paper I, Q.1A(c)"],"options":["Inline","Hierarchical","Single","Multilevel"],"ans":0,"why":"A member function whose body is written inside the class is treated as an inline function."},{"id":"cs-12-03-p902","kind":"mcq","q":"............... is a mechanism to achieve run time polymorphism.","marks":1,"src":["HSC March 2024 Paper I, Q.1A(c)"],"options":["Operator Overloading","Virtual Function","Function Overloading","Constructor"],"ans":1,"why":"A virtual function is bound at run time (late binding), so it gives run time polymorphism. Overloading is resolved at compile time."},{"id":"cs-12-03-p903","kind":"short","q":"State any six principal advantage of object oriented programming.","marks":3,"src":["HSC March 2023 Paper I, Q.2A(b)"],"model":[{"t":"Reuse: a class that is written once can be used again, and inheritance extends it without changing it. This gives less code and fewer mistakes.","m":1},{"t":"Data hiding: the data is private to the object, so it is safe from wrong use by other parts of the program. Several objects of the same class can live together without any clash.","m":1},{"t":"Easy to understand and maintain: the program is divided into objects that match real things, so a fault is found and fixed in one class. It is also easy to extend with new classes, and polymorphism lets one name do different jobs.","m":1}]},{"id":"cs-12-03-p904","kind":"prog","q":"What is Class ? Explain general form of class declaration.","marks":3,"src":["HSC March 2023 Paper I, Q.3A(a)","HSC March 2024 Paper I, Q.4A(a)"],"model":[{"t":"A class is a user defined data type that groups data (data members) and the functions that work on them (member functions). Objects are variables of a class.","m":1},{"t":"General form: the keyword class, the class name, then a body in braces, ended with a semicolon. The body has the private, protected and public sections.","m":1},{"t":"Data members are usually private, and the member functions that the outside needs are public.","m":1}],"code":"class class_name {\nprivate:\n    // data members\nprotected:\n    // members visible to derived classes\npublic:\n    // member functions\n};"},{"id":"cs-12-03-p905","kind":"short","q":"Differentiate between Class and Object.","marks":3,"src":["HSC March 2023 Paper I, Q.4A(b)"],"model":[{"t":"A class is a blueprint (a user defined type). An object is a real variable of that type.","m":1},{"t":"A class takes no memory by itself, only its objects do.","m":1},{"t":"One class can have many objects. Example: class student, objects s1 and s2.","m":1}]},{"id":"cs-12-03-p906","kind":"short","q":"Write any three distinct differences between Procedure Oriented and Object Oriented Programming.","marks":3,"src":["HSC March 2024 Paper I, Q.2A(b)"],"model":[{"t":"Focus: procedure oriented programs are built around functions (steps). Object oriented programs are built around objects (data with functions).","m":1},{"t":"Data: in procedure oriented programs data is global and open to all functions. In object oriented programs data is hidden inside the object.","m":1},{"t":"Approach: procedure oriented programming is top down; object oriented programming is bottom up. Reuse is by inheritance only in the object oriented style. Examples: C and C++.","m":1}]},{"id":"cs-12-03-p907","kind":"short","q":"What is Inheritance ? Identify the types of inheritance of following diagram\ni) A -> B\nii) A and B -> C\niii) A -> B -> C","marks":4,"src":["HSC March 2024 Paper I, Q.4B(a)"],"model":[{"t":"Inheritance is the process by which a new (derived) class takes the data and functions of an existing (base) class and can add its own.","m":1},{"t":"Diagram i): class B is derived from the one class A: single inheritance.","m":1},{"t":"Diagram ii): class C is derived from two classes A and B: multiple inheritance.","m":1},{"t":"Diagram iii): B is derived from A and C is derived from B: multilevel inheritance.","m":1}]},{"id":"cs-12-03-p908","kind":"short","q":"Write functions of each of followings :\ni) ifstream\nii) ofstream\niii) filebuf\niv) fstream","marks":4,"src":["HSC March 2023 Paper I, Q.4B(a)","HSC March 2024 Paper I, Q.4A(c)"],"model":[{"t":"ifstream: an input file stream class. It is used to read data from a file (it has open, get, read and so on).","m":1},{"t":"ofstream: an output file stream class. It is used to write data into a file (put, write).","m":1},{"t":"filebuf: the buffer class of the file stream classes. It sets the file buffer and does the real reading and writing between the program and the file.","m":1},{"t":"fstream: a class for both input and output. A file opened with it can be read and written. All these classes are in the header file fstream.","m":1}]},{"id":"cs-12-03-p909","kind":"prog","q":"Write declaration statements in C++ for:\ni) Pointer to float type\nii) An array of 10 real numbers\niii) An array of 80 characters\niv) An object of class student","marks":4,"src":["HSC March 2024 Paper I, Q.2B(b)"],"model":[{"t":"Pointer to float: float *p;","m":1},{"t":"Array of 10 real numbers: float a[10];","m":1},{"t":"Array of 80 characters: char s[80];","m":1},{"t":"Object of class student: student s1;   (the class student must be declared before).","m":1}],"code":"float *p;\nfloat a[10];\nchar s[80];\nstudent s1;"},{"id":"cs-12-03-p910","kind":"prog","q":"Write C++ program to find a factorial of integers from 1 to 5.","marks":5,"src":["HSC March 2022 Paper I, Q.5(a)"],"model":[{"t":"Include iostream and write main().","m":1},{"t":"An outer loop takes n from 1 to 5.","m":1},{"t":"An inner loop multiplies 1 * 2 * ... * n into a variable f (start from 1).","m":1},{"t":"Print n and f for each n.","m":1},{"t":"Program ends with return 0; the output is 1, 2, 6, 24, 120.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    for (int n = 1; n <= 5; n++) {\n        long f = 1;\n        for (int i = 2; i <= n; i++)\n            f = f * i;\n        cout << n << \"! = \" << f << endl;\n    }\n    return 0;\n}"},{"id":"cs-12-03-p911","kind":"prog","q":"Write a C++ program to count and print occurrence of the character 'M' in a given string of maximum 79 characters.","marks":5,"src":["HSC March 2022 Paper I, Q.5(b)"],"model":[{"t":"Declare a character array of 80 places (79 characters and the end mark), and a counter set to 0.","m":1},{"t":"Read the string with cin.getline so that spaces are accepted.","m":1},{"t":"Walk through the string up to the end mark.","m":1},{"t":"If the character is 'M', add 1 to the counter.","m":1},{"t":"Print the counter.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    char s[80];\n    int count = 0;\n    cout << \"Enter a string (up to 79 characters): \";\n    cin.getline(s, 80);\n    for (int i = 0; s[i] != '\\0'; i++)\n        if (s[i] == 'M')\n            count++;\n    cout << \"M occurs \" << count << \" times\" << endl;\n    return 0;\n}"},{"id":"cs-12-03-p912","kind":"prog","q":"Write C++ program to generate and print first 15 terms of fibonacci series (1, 1, 2, 3, 5, ..........)","marks":5,"src":["HSC March 2022 Paper I, Q.5 OR(b)"],"model":[{"t":"Keep the two latest terms a and b, both 1 at the start, and print them first.","m":1},{"t":"Repeat 13 more times: next = a + b.","m":1},{"t":"Print next, then shift: a takes the value of b, b takes next.","m":1},{"t":"A counter or a for loop controls the 15 terms.","m":1},{"t":"End with return 0.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a = 1, b = 1;\n    cout << a << \" \" << b << \" \";\n    for (int i = 3; i <= 15; i++) {\n        int next = a + b;\n        cout << next << \" \";\n        a = b;\n        b = next;\n    }\n    cout << endl;\n    return 0;\n}"},{"id":"cs-12-03-p913","kind":"prog","q":"Write a C++ program which finds fibonacci series of 'n' terms.","marks":5,"src":["HSC March 2023 Paper I, Q.5(a)"],"model":[{"t":"Read n, the number of terms.","m":1},{"t":"Start with a = 0 and b = 1.","m":1},{"t":"Loop n times: print a, then find next = a + b; set a = b and b = next.","m":1},{"t":"Handle the terms with a for loop.","m":1},{"t":"End with return 0.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cout << \"How many terms? \";\n    cin >> n;\n    long a = 0, b = 1;\n    for (int i = 0; i < n; i++) {\n        cout << a << \" \";\n        long next = a + b;\n        a = b;\n        b = next;\n    }\n    cout << endl;\n    return 0;\n}"},{"id":"cs-12-03-p914","kind":"prog","q":"Write C++ program to find entered number is armstrong number OR NOT armstrong.","marks":5,"src":["HSC March 2023 Paper I, Q.5 OR(a)"],"model":[{"t":"An Armstrong number equals the sum of the cubes of its digits (for three digit numbers). Example: 153 = 1 + 125 + 27.","m":1},{"t":"Read the number and keep a copy of it.","m":1},{"t":"Take the digits one by one with % 10 and / 10 and add the cube of each to a sum.","m":1},{"t":"Compare the sum with the copy.","m":1},{"t":"Print Armstrong or Not Armstrong.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int n, t, d, sum = 0;\n    cout << \"Enter a number: \";\n    cin >> n;\n    t = n;\n    while (t > 0) {\n        d = t % 10;\n        sum = sum + d * d * d;\n        t = t / 10;\n    }\n    if (sum == n)\n        cout << n << \" is an Armstrong number\" << endl;\n    else\n        cout << n << \" is not an Armstrong number\" << endl;\n    return 0;\n}"},{"id":"cs-12-03-p915","kind":"prog","q":"Implement of class average that accepts value of three float variables another function print () average of three numbers.","marks":5,"src":["HSC March 2023 Paper I, Q.5 OR(b)"],"model":[{"t":"Declare class average with three private float data members.","m":1},{"t":"A public function (for example getdata) reads the three values.","m":1},{"t":"A public function print() finds the sum divided by 3 and displays it.","m":1},{"t":"In main() create an object, call the two functions.","m":1},{"t":"The class ends with a semicolon.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nclass average {\n    float a, b, c;\npublic:\n    void getdata() {\n        cout << \"Enter three numbers: \";\n        cin >> a >> b >> c;\n    }\n    void print() {\n        cout << \"Average = \" << (a + b + c) / 3 << endl;\n    }\n};\n\nint main() {\n    average x;\n    x.getdata();\n    x.print();\n    return 0;\n}"},{"id":"cs-12-03-p916","kind":"prog","q":"Write a program in C++ to find Greatest Common, Devisor (GCD) of two inputted number.","marks":5,"src":["HSC March 2024 Paper I, Q.5(a)"],"model":[{"t":"Read the two numbers a and b.","m":1},{"t":"Use the Euclid method: while b is not zero, set r = a % b, a = b and b = r.","m":1},{"t":"When b becomes 0, a is the GCD.","m":1},{"t":"Print the GCD.","m":1},{"t":"End with return 0.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a, b, r;\n    cout << \"Enter two numbers: \";\n    cin >> a >> b;\n    while (b != 0) {\n        r = a % b;\n        a = b;\n        b = r;\n    }\n    cout << \"GCD = \" << a << endl;\n    return 0;\n}"},{"id":"cs-12-03-p917","kind":"prog","q":"Write a program in C++ to accept 10 integers in an array from keyboard and find largest element of array.","marks":5,"src":["HSC March 2024 Paper I, Q.5(b)"],"model":[{"t":"Declare an array of 10 integers.","m":1},{"t":"Read the 10 values with a for loop.","m":1},{"t":"Take the first element as the largest so far.","m":1},{"t":"Compare the others with it and replace it when a bigger one is found.","m":1},{"t":"Print the largest.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[10], i, big;\n    cout << \"Enter 10 integers: \";\n    for (i = 0; i < 10; i++)\n        cin >> a[i];\n    big = a[0];\n    for (i = 1; i < 10; i++)\n        if (a[i] > big)\n            big = a[i];\n    cout << \"Largest = \" << big << endl;\n    return 0;\n}"},{"id":"cs-12-03-p918","kind":"prog","q":"Write a program in C++ to create a class test having member functions getmarks () to read marks of two subjects and showsum () to display the total marks.","marks":5,"src":["HSC March 2024 Paper I, Q.5 OR(a)"],"model":[{"t":"Declare class test with two private data members for the marks.","m":1},{"t":"getmarks() reads the marks of the two subjects.","m":1},{"t":"showsum() adds them and displays the total.","m":1},{"t":"In main() create an object and call getmarks() and then showsum().","m":1},{"t":"The class definition ends with a semicolon.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nclass test {\n    int m1, m2;\npublic:\n    void getmarks() {\n        cout << \"Enter marks of two subjects: \";\n        cin >> m1 >> m2;\n    }\n    void showsum() {\n        cout << \"Total marks = \" << m1 + m2 << endl;\n    }\n};\n\nint main() {\n    test t;\n    t.getmarks();\n    t.showsum();\n    return 0;\n}"},{"id":"cs-12-03-p919","kind":"prog","q":"Write a program in C++ to read three integers and find smallest of these numbers.","marks":5,"src":["HSC March 2024 Paper I, Q.5 OR(b)"],"model":[{"t":"Read the three integers a, b and c.","m":1},{"t":"Assume a is the smallest in a variable small.","m":1},{"t":"If b is smaller than small, small = b.","m":1},{"t":"If c is smaller than small, small = c.","m":1},{"t":"Print small.","m":1}],"code":"#include <iostream>\nusing namespace std;\n\nint main() {\n    int a, b, c, small;\n    cout << \"Enter three integers: \";\n    cin >> a >> b >> c;\n    small = a;\n    if (b < small)\n        small = b;\n    if (c < small)\n        small = c;\n    cout << \"Smallest = \" << small << endl;\n    return 0;\n}"}];
